10 // Specifying the problem: whether `s[i..j]` is palindromic
11 ghost predicate palindromic(s: string, i: int, j: int)
12   requires 0 <= i <= j <= |s|
13   decreases j - i
14 {
15   j - i < 2 || (s[i] == s[j-1] && palindromic(s, i+1, j-1))
16 }
17 
18 // A "common sense" about palindromes:
19 lemma lemma_palindromic_contains(s: string, lo: int, hi: int, lo': int, hi': int)
20   requires 0 <= lo <= lo' <= hi' <= hi <= |s|
21   requires lo + hi == lo' + hi'
22   requires palindromic(s, lo, hi)
23   ensures palindromic(s, lo', hi')
24   decreases lo' - lo
25 {
26   if lo < lo' {
27     lemma_palindromic_contains(s, lo + 1, hi - 1, lo', hi');
28   }
29 }
30 
31 // A useful "helper function" that returns the longest palindrome at a given center (i0, j0).
32 method expand_from_center(s: string, i0: int, j0: int) returns (lo: int, hi: int)
33   requires 0 <= i0 <= j0 <= |s|
34   requires palindromic(s, i0, j0)
35   ensures 0 <= lo <= hi <= |s| && palindromic(s, lo, hi)
36   ensures forall i, j | 0 <= i <= j <= |s| && palindromic(s, i, j)  // Among all palindromes
37     && i + j == i0 + j0                                             // sharing the same center,
38     :: j - i <= hi - lo                                             // `s[lo..hi]` is longest.
39 {
40   lo, hi := i0, j0;
41 
42   // we try expanding whenever possible:
43   while lo - 1 >= 0 && hi < |s| && s[lo - 1] == s[hi]
44     invariant 0 <= lo <= hi <= |s| && lo + hi == i0 + j0
45     invariant palindromic(s, lo, hi)
46   {
47     lo, hi := lo - 1, hi + 1;
48   }
49 
50   // proves that we cannot go further:
51   forall i, j | 0 <= i <= j <= |s| && i + j == i0 + j0 && j - i > hi - lo ensures !palindromic(s, i, j) {
52     if palindromic(s, i, j) { // prove by contradiction:
53       lemma_palindromic_contains(s, i, j, lo - 1, hi + 1);
54     }
55   }
56 }
