59 // The main algorithm.
60 // We traverse all centers from left to right, and "expand" each of them, to find the longest palindrome.
61 method longestPalindrome(s: string) returns (ans: string, lo: int, hi: int)
62   ensures 0 <= lo <= hi <= |s| && ans == s[lo..hi]  // `ans` is indeed a substring in `s`
63   ensures palindromic(s, lo, hi)  // `ans` is palindromic
64   ensures forall i, j | 0 <= i <= j <= |s| && palindromic(s, i, j) :: j - i <= hi - lo  // `ans` is longest
65 {
66   lo, hi := 0, 0;
67   for k := 0 to |s|
68     invariant 0 <= lo <= hi <= |s|
69     invariant palindromic(s, lo, hi)
70     invariant forall i, j | 0 <= i <= j <= |s| && i + j < 2 * k && palindromic(s, i, j) :: j - i <= hi - lo
71   {
72     var a, b := expand_from_center(s, k, k);
73     if b - a > hi - lo {
74       lo, hi := a, b;
75     }
76     var c, d := expand_from_center(s, k, k + 1);
77     if d - c > hi - lo {
78       lo, hi := c, d;
79     }
80   }
81   return s[lo..hi], lo, hi;
82 }
