114 // A reference implementation of Manacher's algorithm:
115 // (Ref. https://en.wikipedia.org/wiki/Longest_palindromic_substring#Manacher's_algorithm) for details...
116 method {:vcs_split_on_every_assert} longestPalindrome'(s: string) returns (ans: string, lo: int, hi: int)
117   ensures 0 <= lo <= hi <= |s| && ans == s[lo..hi]
118   ensures palindromic(s, lo, hi)
119   ensures forall i, j | 0 <= i <= j <= |s| && palindromic(s, i, j) :: j - i <= hi - lo
120 {
121   var bogus: char :| true;  // an arbitrary character
122   var s' := insert_bogus_chars(s, bogus);
123   var radii := new int[|s'|];
124   var center, radius := 0, 0;
125   // vars below are just for verifying time complexity:
126   ghost var loop_counter_outer, loop_counter_inner1, loop_counter_inner2 := 0, 0, 0;
127 
128   while center < |s'|
129     invariant 0 <= center <= |s'|
130     invariant forall c | 0 <= c < center :: max_radius(s', c, radii[c])
131     invariant center < |s'| ==> inbound_radius(s', center, radius) && palindromic_radius(s', center, radius)
132     invariant center == |s'| ==> radius == 0
133     invariant loop_counter_outer <= center
134     invariant loop_counter_inner1 <= center + radius && loop_counter_inner2 <= (center) + 1
135   {
136     loop_counter_outer := loop_counter_outer + 1;
137 
138     // Stage 1: Still the normal "expand from center" routine, except `radius` is NOT necessarily zero:
139     while center - (radius + 1) >= 0 && center + (radius + 1) < |s'|
140         && s'[center - (radius + 1)] == s'[center + (radius + 1)]
141       decreases center - radius
142       invariant inbound_radius(s', center, radius) && palindromic_radius(s', center, radius)
143       invariant loop_counter_inner1 <= center + radius
144     {
145       loop_counter_inner1 := loop_counter_inner1 + 1;
146       radius := radius + 1;
147     }
148     lemma_end_of_expansion(s', center, radius);
149 
150     radii[center] := radius;
151     var old_center, old_radius := center, radius;
152     center := center + 1;
153     radius := 0;
154 
155     // Stage 2: Quickly infer the maximal radius, using the symmetry of known palindromes. 
156     while center <= old_center + old_radius
157       invariant 0 <= center <= |s'|
158       invariant forall c | 0 <= c < center :: max_radius(s', c, radii[c])
159       invariant center < |s'| ==> inbound_radius(s', center, radius) && palindromic_radius(s', center, radius)
160       invariant loop_counter_inner2 <= center - 1
161     {
162       loop_counter_inner2 := loop_counter_inner2 + 1;
163 
164       var mirrored_center := old_center - (center - old_center);
165       var max_mirrored_radius := old_center + old_radius - center;
166       lemma_mirrored_palindrome(s', old_center, old_radius, mirrored_center, radii[mirrored_center], center);
167 
168       if radii[mirrored_center] < max_mirrored_radius {
169         radii[center] := radii[mirrored_center];
170         center := center + 1;
171       } else if radii[mirrored_center] > max_mirrored_radius {
172         radii[center] := max_mirrored_radius;
173         center := center + 1;
174       } else {
175         radius := max_mirrored_radius;
176         break;
177       }
178     }
179   }
180   // verify that the worst time complexity (measured by loop iterations) is O(|s'|) == O(|s|):
181   assert |s'| == 2 * |s| + 1;
182   assert loop_counter_outer <= |s'|;
183   assert loop_counter_inner1 <= |s'|;
184   assert loop_counter_inner2 <= |s'|; 
185 
186   // wrap up results:
187   var (c, r) := argmax(radii, 0);
188   lo, hi := (c - r) / 2, (c + r) / 2; // notice that both ends are bogus chars at position 0, 2, 4, 6, etc.!
189   lemma_result_transfer(s, s', bogus, radii, c, r, hi, lo);
190   return s[lo..hi], lo, hi;        
191 }
