194 // Below are helper functions and lemmas we used:
195 
196 // Inserts bogus characters to the original string (e.g. from `abc` to `|a|b|c|`).
197 // Note that this is neither efficient nor necessary in reality, but just for the ease of understanding.
198 function {:opaque} insert_bogus_chars(s: string, bogus: char): (s': string)
199   ensures |s'| == 2 * |s| + 1
200   ensures forall i | 0 <= i <= |s| :: s'[i * 2] == bogus
201   ensures forall i | 0 <= i < |s| :: s'[i * 2 + 1] == s[i]
202 {
203   if s == "" then
204     [bogus]
205   else
206     var s'_old := insert_bogus_chars(s[1..], bogus);
207     var s'_new := [bogus] + [s[0]] + s'_old;
208     assert forall i | 1 <= i <= |s| :: s'_new[i * 2] == s'_old[(i-1) * 2];
209     s'_new
210 }
211 
212 // Returns (max_index, max_value) of array `a` starting from index `start`.
213 function {:opaque} argmax(a: array<int>, start: int): (res: (int, int))
214   reads a
215   requires 0 <= start < a.Length
216   ensures start <= res.0 < a.Length && a[res.0] == res.1
217   ensures forall i | start <= i < a.Length :: a[i] <= res.1
218   decreases a.Length - start
219 {
220   if start == a.Length - 1 then
221     (start, a[start])
222   else
223     var (i, v) := argmax(a, start + 1);
224     if a[start] >= v then (start, a[start]) else (i, v)
225 }
