227 // Whether an interval at center `c` with a radius `r` is within the boundary of `s'`.
228 ghost predicate inbound_radius(s': string, c: int, r: int)
229 {
230   r >= 0 && 0 <= c-r && c+r < |s'|
231 }
232 
233 // Whether `r` is a valid palindromic radius at center `c`.
234 ghost predicate palindromic_radius(s': string, c: int, r: int)
235   requires inbound_radius(s', c, r)
236 {
237   palindromic(s', c-r, c+r+1)
238 }
239 
240 // Whether `r` is the maximal palindromic radius at center `c`.
241 ghost predicate max_radius(s': string, c: int, r: int)
242 {
243   && inbound_radius(s', c, r)
244   && palindromic_radius(s', c, r)
245   && (forall r' | r' > r && inbound_radius(s', c, r') :: !palindromic_radius(s', c, r'))
246 }
