248 // Basically, just "rephrasing" the `lemma_palindromic_contains`,
249 // talking about center and radius, instead of interval
250 lemma lemma_palindromic_radius_contains(s': string, c: int, r: int, r': int)
251   requires inbound_radius(s', c, r) && palindromic_radius(s', c, r)
252   requires 0 <= r' <= r
253   ensures inbound_radius(s', c, r') && palindromic_radius(s', c, r')
254 {
255   lemma_palindromic_contains(s', c-r, c+r+1, c-r', c+r'+1);
256 }
