258 // When "expand from center" ends, we've find the max radius:
259 lemma lemma_end_of_expansion(s': string, c: int, r: int)
260   requires inbound_radius(s', c, r) && palindromic_radius(s', c, r)
261   requires inbound_radius(s', c, r + 1) ==> s'[c - (r + 1)] != s'[c + (r + 1)]
262   ensures max_radius(s', c, r)
263 {
264   forall r' | r' > r && inbound_radius(s', c, r') ensures !palindromic_radius(s', c, r') {
265     if palindromic_radius(s', c, r') {  // proof by contradiction
266       lemma_palindromic_radius_contains(s', c, r', r+1);
267     }
268   }
