271 // The critical insight behind Manacher's algorithm.
272 //
273 // Given the longest palindrome centered at `c` has length `r`, consider the interval from `c-r` to `c+r`.
274 // Consider a pair of centers in the interval: `c1` (left half) and `c2` (right half), equally away from `c`.
275 // Then, the length of longest palindromes at `c1` and `c2` are related as follows:
276 lemma lemma_mirrored_palindrome(s': string, c: int, r: int, c1: int, r1: int, c2: int)
277   requires max_radius(s', c, r) && max_radius(s', c1, r1)
278   requires c - r <= c1 < c < c2 <= c + r
279   requires c2 - c == c - c1
280   ensures c2 + r1 < c + r ==> max_radius(s', c2, r1)
281   ensures c2 + r1 > c + r ==> max_radius(s', c2, c + r - c2)
282   ensures c2 + r1 == c + r ==> palindromic_radius(s', c2, c + r - c2)
283 {
284   // proof looks long, but is quite straightforward at each step:
285   if c2 + r1 < c + r {
286     for r2 := 0 to r1
287       invariant palindromic_radius(s', c2, r2)
288     {
289       var r2' := r2 + 1;
290       assert s'[c1+r2'] == s'[c2-r2'] by { lemma_palindromic_radius_contains(s', c, r, abs(c - c1 - r2')); }
291       assert s'[c1-r2'] == s'[c2+r2'] by { lemma_palindromic_radius_contains(s', c, r, abs(c - c1 + r2')); }
292       assert s'[c1-r2'] == s'[c1+r2'] by { lemma_palindromic_radius_contains(s', c1, r1, r2'); }
293     }
294     var r2' := r1 + 1;
295     assert s'[c1+r2'] == s'[c2-r2'] by { lemma_palindromic_radius_contains(s', c, r, abs(c - c1 - r2')); }
296     assert s'[c1-r2'] == s'[c2+r2'] by { lemma_palindromic_radius_contains(s', c, r, abs(c - c1 + r2')); }
297     assert s'[c1-r2'] != s'[c1+r2'] by { assert !palindromic_radius(s', c1, r2'); }
298     lemma_end_of_expansion(s', c2, r1);
299   } else {
300     for r2 := 0 to c + r - c2
301       invariant palindromic_radius(s', c2, r2)
302     {
303       var r2' := r2 + 1;
304       assert s'[c1+r2'] == s'[c2-r2'] by { lemma_palindromic_radius_contains(s', c, r, abs(c - c1 - r2')); }
305       assert s'[c1-r2'] == s'[c2+r2'] by { lemma_palindromic_radius_contains(s', c, r, abs(c - c1 + r2')); }
306       assert s'[c1-r2'] == s'[c1+r2'] by { lemma_palindromic_radius_contains(s', c1, r1, r2'); }
307     }
308     if c2 + r1 > c + r {
309       var r2' := (c + r - c2) + 1;
310       if inbound_radius(s', c, r + 1) {
311         assert s'[c1+r2'] == s'[c2-r2'] by { lemma_palindromic_radius_contains(s', c, r, abs(c - c1 - r2')); }
312         assert s'[c1-r2'] != s'[c2+r2'] by { assert !palindromic_radius(s', c, r + 1); }
313         assert s'[c1-r2'] == s'[c1+r2'] by { lemma_palindromic_radius_contains(s', c1, r1, r2'); }
314         lemma_end_of_expansion(s', c2, c + r - c2);
315       }
316     }
317   }
318 }
