325 lemma lemma_result_transfer(s: string, s': string, bogus: char, radii: array<int>, c: int, r: int, hi: int, lo: int)
326   requires s' == insert_bogus_chars(s, bogus)
327   requires radii.Length == |s'|
328   requires forall i | 0 <= i < radii.Length :: max_radius(s', i, radii[i])
329   requires (c, r) == argmax(radii, 0)
330   requires lo == (c - r) / 2 && hi == (c + r) / 2
331   ensures 0 <= lo <= hi <= |s|
332   ensures palindromic(s, lo, hi)
333   ensures forall i, j | 0 <= i <= j <= |s| && palindromic(s, i, j) :: j - i <= hi - lo
334 {
335   // For each center, rephrase [maximal radius in `s'`] into [maximal interval in `s`]:
336   forall k | 0 <= k < radii.Length
